    app.ui.view = crate::state::ViewMode::PhotoGrid;
    let mut h = Headless::new(app, [1300.0, 1000.0], 1.0);
{ ... }
    let Some(crate::state::Dialog::Import { opts }) = &mut h.app.ui.dialog else { panic!("dialog closed") };
